import 'dart:convert';

import 'package:serverdeck_protocol/codec.dart';
import 'package:serverdeck_protocol/mcp/wire.dart';
import 'package:serverdeck_protocol/validation.dart';

/// Public mutation intent only. Job/attempt IDs and execution authority are
/// resolved/generated by the native service, never supplied by an AI caller.
final class JobMutationCommand {
  factory JobMutationCommand.parse(
    String operation,
    Map<String, Object?> value,
  ) {
    if (!const {'job.apply', 'job.cancel', 'job.reconcile'}.contains(operation))
      throw const FormatException('VALIDATION');
    final input = StrictCodec().decode(
      encodeMcpMessage(value, maxBytes: 256 * 1024),
      maxBytes: 256 * 1024,
    );
    requireFields(input, {
      'requestId',
      operation == 'job.apply' ? 'planId' : 'jobId',
    });
    for (final value in input.values) requireUuid(value);
    return JobMutationCommand._(operation, jsonEncode(input));
  }
  const JobMutationCommand._(this.operation, this._json);
  final String operation, _json;
  Map<String, Object?> toJson() => jsonDecode(_json) as Map<String, Object?>;
  String get requestId => toJson()['requestId'] as String;
  Map<String, Object?> canonicalRequest(String? origin) => {
    'operation': operation,
    'originGrantId': origin,
    'params': {...toJson()}..remove('requestId'),
  };
}
